// Siapkan sinkron kasir → sheet pusat: baca tab `config` di "Rekap Omzet (Master)", tentukan periode & file tujuan.
// Output 1 item: {ok, sekarang, tanggal, tahun, bulan, tgl, sync_bulan_lalu, bulan_lalu, tahun_lalu, tab_arsip,
//   doc_ini, doc_lalu, tab_data, hari_sync_bulan_lalu, status_terkunci:[..], jam_lapor_konflik, zona, gagal:[], catatan:[]}
const BULAN = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
const baca = node => {
  for (const n of [node, 1, 2, 3, 4, 5].map((x, i) => i ? node + x : node)) {
    try { return $(n).all().map(it => it.json); } catch (e) { /* coba nama berikutnya */ }
  }
  return null;
};
const gagal = [], catatan = [];
const rows = baca('Baca Config');
if (rows === null || rows.some(x => x && x.error)) gagal.push('Baca Config');
const cfg = {};
for (const r of rows || []) {
  const k = String(r.key ?? r.Key ?? '').trim(); if (k) cfg[k] = r.value ?? r.Value ?? '';
}
const zona = String(cfg.zona || 'Asia/Makassar');
