const fmt = String(cfg.format_tab_arsip || '{Bulan}{Tahun}');
const tabArsip = fmt.replace('{Bulan}', BULAN[lalu.month - 1]).replace('{Tahun}', String(lalu.year)).replace('{MM}', String(lalu.month).padStart(2, '0'));
const docIni = String(cfg['data_file_' + now.year] || '').trim();
const docLalu = String(cfg['data_file_' + lalu.year] || '').trim();
const sync = now.day <= hariLalu;
if (!docIni) catatan.push('config data_file_' + now.year + ' belum diisi — buat file "Data Omzet Harian ' + now.year + '" lalu isi id-nya di tab config');
if (sync && !docLalu) catatan.push('config data_file_' + lalu.year + ' belum diisi');
