  ok: gagal.length === 0 && !!docIni,
  sekarang: now.toISO({ suppressMilliseconds: true }), tanggal: now.toISODate(), tahun: now.year, bulan: now.toFormat('yyyy-MM'), tgl: now.day,
  sync_bulan_lalu: sync, bulan_lalu: lalu.toFormat('yyyy-MM'), tahun_lalu: lalu.year, tab_arsip: tabArsip,
  doc_ini: docIni || 'BELUM-DIISI', doc_lalu: (sync ? docLalu : '') || docIni || 'BELUM-DIISI', tab_data: String(cfg.tab_data || 'data'),
  hari_sync_bulan_lalu: hariLalu,
  status_terkunci: String(cfg.status_terkunci || 'terverifikasi,kunci').split(',').map(s => s.trim().toLowerCase()).filter(Boolean),
  jam_lapor_konflik: Number(cfg.jam_lapor_konflik ?? 7), zona, gagal, catatan } }];

// Hitung sinkron Penutupan Kasir → "Data Omzet Harian <tahun>" (tab data) + rekap di "Rekap Omzet (Master)".
// Input: Siapkan, Baca Target (master/target), Baca Data Tahun Ini, Baca Kasir <Outlet> ×7 (BulanBerlangsung A1:Z60),
//   [hari 1..hari_sync_bulan_lalu] Baca Arsip <Outlet> ×7 (tab arsip bulan lalu) + Baca Data Tahun Lalu.
// Kolom kasir dipetakan per NAMA judul (dinormalisasi; sama persis dengan backfill.py) — posisi kolom boleh beda antar file/bulan.
// Aturan upsert (kunci = outlet_kode|tanggal):
//   - baris baru → tulis; row_hash beda → tulis; row_hash sama → lewati.
//   - baris di pusat ber-status terkunci (config status_terkunci, default terverifikasi,kunci) TIDAK ditimpa;
//     bila isi kasir berbeda → dicatat di log sebagai konflik (sekali sehari, jam jam_lapor_konflik).
//   - tanggal yang ada di tab arsip dan BulanBerlangsung → arsip dipakai.
//   - kalau sheet pusat gagal dibaca → TIDAK menulis data apa pun (supaya baris terkunci aman), hanya log.
// omzet = tunai + qris + ojol (tanpa ongkir). Bulan lama tanpa pemisahan QRIS/Ojol: non_tunai_total saja.
// Channel (tab ChannelHarian per outlet, dibaca node Baca Channel <Outlet>, judul dicocokkan per NAMA, huruf besar/kecil bebas):
//   Offline→ch_offline, Whatsapp→ch_whatsapp, Ojol→ch_ojol, ch_selisih = total channel − total_kaspin (hanya hari yang ada isinya).
//   ch_* = data marketing → TIDAK ikut kunci verifikasi & tidak masuk row_hash; dibandingkan langsung dengan nilai pusat (idempoten).
//   Tanggal yang tidak ada di tab / tab gagal dibaca → nilai ch_* di pusat dibiarkan. Baris tab ada tapi kosong → ch_* dikosongkan.
// Online admin (tab OnlineHarian per outlet, diisi ADMIN, dibaca node Baca Online <Outlet>; judul Tanggal, Online Organik|Organik, Online Ads|Ads,
//   Live Shopping|Live (OPSIONAL: tab versi lama tanpa kolom Live tetap jalan, ch_live dikosongkan)):
//   → ch_organik, ch_ads, ch_live. ch_whatsapp tetap = WhatsApp versi kasir.
//   ch_online = organik+ads+live bila admin sudah isi (ch_online_sumber 'admin'), kalau belum = WhatsApp kasir ('kasir'), kosong bila dua-duanya kosong.
//   ch_selisih_online = (organik+ads+live) − WhatsApp kasir (hanya bila dua-duanya diisi). ch_selisih TETAP = total channel KASIR − total_kaspin.
//   Tab OnlineHarian belum ada / gagal dibaca → TIDAK membuat ok:false (opsional): dicatat di ringkas.gagal_opsional, masuk log sekali sehari.
//   Kolom ch_organik… belum ada di file Data Omzet Harian → kolom itu tidak dibandingkan (tidak menulis berulang) + catatan untuk menambah kolom.
// Output 1 item: {tulis_ini:[], tulis_lalu:[], rekap_mingguan:[], rekap_bulanan:[], rekap_tahunan:[], log:[0..1], ringkas:{...}}
const OUTLET = [
  { kode: 'SPO', nama: 'Sungai Poso', node: 'Sungai Poso' },
  { kode: 'GWA', nama: 'Gowa', node: 'Gowa' },
  { kode: 'SDG', nama: 'Sudiang', node: 'Sudiang' },        // = GOA RIA di Target Control
  { kode: 'BRB', nama: 'Barombong', node: 'Barombong' },
  { kode: 'LMB', nama: 'Limbung', node: 'Limbung' },
  { kode: 'PRE', nama: 'Pare-Pare', node: 'Pare-Pare' },
  { kode: 'TML', nama: 'Tamalate', node: 'Tamalate' }];
const COLS = ['key','tanggal','bulan','minggu_ke','outlet_kode','outlet_nama','paket','kasir','total_kaspin','tunai','qris','ojol',
  'non_tunai_total','omzet','ongkir_masuk','tunai_real','uang_tunai_ada','ongkir_keluar','real_qris','real_ojol',
  'penyesuaian_tunai','ket_peny_tunai','penyesuaian_nontunai','ket_peny_nontunai','verif_finance','verif_spv','status',
  'ch_offline','ch_whatsapp','ch_ojol','ch_selisih','sumber','row_hash','synced_at',
  'ch_organik','ch_ads','ch_online','ch_online_sumber','ch_selisih_online',   // tambahan OnlineHarian (di akhir tabel, AI:AM)
  'ch_live'];   // AN: Live Shopping (admin). Flow menulis per NAMA judul kolom, jadi posisi kolom bebas.
const HASH_FIELDS = ['tanggal','outlet_kode','paket','kasir','total_kaspin','tunai','qris','ojol','non_tunai_total','omzet','ongkir_masuk',
  'tunai_real','uang_tunai_ada','ongkir_keluar','real_qris','real_ojol','penyesuaian_tunai','ket_peny_tunai',
  'penyesuaian_nontunai','ket_peny_nontunai','verif_finance','verif_spv'];
const NUMF = new Set(['paket','total_kaspin','tunai','qris','ojol','_nt_gabung','ongkir_masuk','tunai_real','uang_tunai_ada','ongkir_keluar',
  'real_qris','real_ojol','_real_nt_gabung','penyesuaian_tunai','penyesuaian_nontunai','_saldo_deposit']);
const BLN = { JAN: 1, FEB: 2, MAR: 3, APR: 4, MEI: 5, MAY: 5, JUN: 6, JUL: 7, AGU: 8, AGT: 8, AUG: 8, SEP: 9, OKT: 10, OCT: 10, NOV: 11, NOP: 11, DES: 12, DEC: 12 };
const t = v => (v == null ? '' : String(v).trim());
const norm = h => t(h).toUpperCase().replace(/N0N/g, 'NON').replace(/[^A-Z0-9]/g, '');
function fieldOf(n, hasRealOjol, hasOjol) {
  if (n === 'TANGGAL') return 'tanggal';
  if (n === 'PENJUALANPAKET') return 'paket';
  if (n === 'SALDOAWALDEPOSIT') return '_saldo_deposit';
  if (n === 'NAMAKASIR') return 'kasir';
  if (n === 'TOTALKASPIN') return 'total_kaspin';
  if (n === 'PENJUALANTUNAI') return 'tunai';
  if (n.startsWith('PENJUALANNONTUNAIQRIS')) return 'qris';
  if (n.startsWith('PENJUALANNONTUNAIOJOL')) return 'ojol';
  if (n === 'PENJUALANNONTUNAI') return hasOjol ? 'qris' : '_nt_gabung';
  if (n === 'PEMASUKANONGKIR') return 'ongkir_masuk';
  if (n === 'TUNAIREAL') return 'tunai_real';
  if (n === 'UANGTUNAIYANGADA') return 'uang_tunai_ada';
  if (n === 'PENGELUARANONGKIR') return 'ongkir_keluar';
  if (n.startsWith('NONTUNAIREALQRIS')) return 'real_qris';
  if (n.startsWith('NONTUNAIREALOJOL')) return 'real_ojol';
  if (n === 'NONTUNAIREAL') return hasRealOjol ? 'real_qris' : '_real_nt_gabung';
  if (n === 'PENYESUAIANTUNAI') return 'penyesuaian_tunai';
  if (n === 'KETERANGAN') return 'ket_peny_tunai';
  if (n === 'PENYESUAIANNONTUNAI') return 'penyesuaian_nontunai';
  if (n === 'KETERANGAN2') return 'ket_peny_nontunai';
  if (n === 'VERIFIKASIFINANCE') return 'verif_finance';
  if (n.startsWith('VERIFIKASISPV')) return 'verif_spv';
