}
const num = v => {
  if (typeof v === 'boolean') return null;
  if (typeof v === 'number') return isFinite(v) ? v : null;
  let s = t(v).replace(/rp/ig, '').replace(/ /g, '');
  if (!s || s === '-' || s.startsWith('#')) return null;
  if (/^-?\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) s = s.replace(/\./g, '').replace(',', '.'); else s = s.replace(/,/g, '');
  if (!/^[-+]?(\d+\.?\d*|\.\d+)(e[-+]?\d+)?$/i.test(s)) return null;
  const n = Number(s); return isFinite(n) ? n : null;
};
const boolv = v => {
  if (typeof v === 'boolean') return v;
  const s = t(v).toUpperCase();
  return ['TRUE','YA','1','V','✓'].includes(s) ? true : ['FALSE','TIDAK','0',''].includes(s) ? false : null;
};
const pad = n => String(n).padStart(2, '0');
// → 'YYYY-MM-DD' | null. Serial Sheets / "2026-10-01" / "01/10/2026" / "1 Oktober 2026"
const toISO = v => {
  if (typeof v === 'number') { if (!(v > 20000 && v < 80000)) return null; const d = new Date(Date.UTC(1899, 11, 30) + Math.floor(v) * 864e5); return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()); }
  const s = t(v); let m;
  if ((m = /^(\d{4})-(\d{1,2})-(\d{1,2})/.exec(s))) return m[1] + '-' + pad(m[2]) + '-' + pad(m[3]);
  if ((m = /^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})/.exec(s))) return m[3] + '-' + pad(m[2]) + '-' + pad(m[1]);
  if ((m = /^(\d{1,2})\s+([A-Za-z]{3})[A-Za-z]*\.?\s+(\d{4})/.exec(s)) && BLN[m[2].toUpperCase()]) return m[3] + '-' + pad(BLN[m[2].toUpperCase()]) + '-' + pad(m[1]);
  if (/^\d+(\.\d+)?$/.test(s)) return toISO(Number(s));
  return null;
};
const canon = v => {
  if (v === null || v === undefined || v === '') return '';
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE';
  if (typeof v === 'number') return Math.abs(v - Math.round(v)) < 1e-9 ? String(Math.round(v)) : v.toFixed(4).replace(/0+$/, '').replace(/\.$/, '');
  return String(v).replace(/\s+/g, ' ').trim();
};
const cyrb53 = (str, seed = 0) => {   // hash 53-bit (sama dengan backfill.py)
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0; i < str.length; i++) { const ch = str.charCodeAt(i); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16).padStart(14, '0');
