const rowHash = r => cyrb53(HASH_FIELDS.map(f => canon(r[f])).join('|'));
const mingguKe = d => (d <= 7 ? 1 : d <= 14 ? 2 : d <= 21 ? 3 : 4);
const statusOf = r => (r.verif_finance && r.verif_spv ? 'terverifikasi' : (r.verif_finance || r.verif_spv) ? 'sebagian' : 'belum');
const baca = node => {
  for (const n of [node, 1, 2, 3, 4, 5].map((x, i) => i ? node + x : node)) {
    try { return $(n).all().map(it => it.json); } catch (e) { /* coba nama berikutnya */ }
  }
  return null;
};
const gagal = [], catatan = [];
const rowsOf = (node, wajib = true) => {
  const r = baca(node);
  if (r === null) { if (wajib) gagal.push(node); return null; }
  if (r.some(x => x && x.error)) { gagal.push(node); return null; }
  return r.filter(x => x && Object.keys(x).some(k => k !== 'row_number'));
};

// ---- parse satu tab kasir (array objek {judul: nilai}) → baris pusat ----
function parseTab(rows, o, sumber, s) {
  if (!rows || !rows.length) return [];
  const heads = [];
  for (const r of rows) for (const k of Object.keys(r)) if (k !== 'row_number' && !heads.includes(k)) heads.push(k);
  const N = heads.map(norm);
  const hasRO = N.some(h => h.startsWith('NONTUNAIREALOJOL')), hasOJ = N.some(h => h.startsWith('PENJUALANNONTUNAIOJOL'));
  const cand = {};
  heads.forEach((h, i) => { const f = fieldOf(N[i], hasRO, hasOJ); if (f) (cand[f] = cand[f] || []).push(h); });
  const pick = {};
  for (const [f, hs] of Object.entries(cand)) {   // judul ganda → kolom yang paling banyak isinya
    let best = hs[0], bn = -1;
    for (const h of hs) { const n = rows.filter(r => r[h] !== undefined && r[h] !== null && r[h] !== '').length; if (n > bn) { bn = n; best = h; } }
    pick[f] = best;
  }
  if (!pick.tanggal) { catatan.push(o.nama + ' (' + sumber + '): kolom Tanggal tidak ditemukan'); return []; }
  const split = !!(pick.qris || pick.ojol);
  const out = [];
  for (const r of rows) {
    let tg = toISO(r[pick.tanggal]);
    if (!tg) continue;
    const rec = {};
    for (const [f, h] of Object.entries(pick)) {
      if (f === 'tanggal') continue;
      const v = r[h];
      if (NUMF.has(f)) rec[f] = num(v);
      else if (f === 'verif_finance' || f === 'verif_spv') rec[f] = boolv(v);
      else rec[f] = (v === undefined || v === null || v === '') ? '' : canon(v);
    }
    if ([rec.tunai, rec.qris, rec.ojol, rec._nt_gabung].every(v => !v) && !rec.kasir && !rec.total_kaspin) continue;   // tanggal belum diisi
    // tahun salah ketik (mis. 5026-02-04) → pakai tahun periode bila bulannya cocok
    const ym = tg.slice(0, 7);
    if (!s.bulanOK.includes(ym)) {
      const fix = s.bulanOK.find(b => b.slice(5) === tg.slice(5, 7));
      if (fix && Math.abs(+tg.slice(0, 4) - +fix.slice(0, 4)) > 0) { catatan.push(o.nama + ' ' + sumber + ' baris ' + r.row_number + ': tahun ' + tg + ' → ' + fix + tg.slice(7)); tg = fix + tg.slice(7); }
      else { s.luar.push(o.nama + ' ' + tg); continue; }
    }
    if (tg > s.tanggal) { s.luar.push(o.nama + ' ' + tg + ' (masa depan)'); continue; }
    const tunai = rec.tunai || 0;
    let nt;
    if (split) nt = (rec.qris || 0) + (rec.ojol || 0);
    else { nt = rec._nt_gabung || 0; rec.qris = null; rec.ojol = null; if (rec._real_nt_gabung !== undefined && rec._real_nt_gabung !== null) rec.real_qris = rec._real_nt_gabung; }
    if (!pick.paket) rec.paket = null;
    const x = { key: o.kode + '|' + tg, tanggal: tg, bulan: tg.slice(0, 7), minggu_ke: mingguKe(+tg.slice(8)), outlet_kode: o.kode, outlet_nama: o.nama };
    for (const c of COLS) if (c in rec) x[c] = rec[c];
    x.non_tunai_total = nt; x.omzet = tunai + nt;
    x.status = statusOf(x);
    x.ch_offline = ''; x.ch_whatsapp = ''; x.ch_ojol = ''; x.ch_selisih = '';
    x.sumber = sumber === 'BulanBerlangsung' ? 'live' : 'arsip:' + sumber;
    x.row_hash = rowHash(x); x.synced_at = s.sekarang; x._row = r.row_number;
    out.push(x);
  }
