}

// ---- rekap (dipakai juga untuk backfill: lihat test) ----
// <rekap>
function rekap(dataRows, targetRows, bulanList, tahunList, sekarang, outlets) {
  const nm = Object.fromEntries(outlets.map(o => [o.kode, o.nama]));
  const urut = Object.fromEntries(outlets.map((o, i) => [o.kode, i]));
  const tgt = {};
  for (const r of targetRows || []) {
    const b = t(r.bulan).slice(0, 7), k = t(r.outlet_kode).toUpperCase(); if (!b || !k) continue;
    const tb = num(r.target_bulanan);
    const bob = [1, 2, 3, 4].map(i => num(r['bobot_m' + i]));
    const tm = [1, 2, 3, 4].map((i, j) => { const v = num(r['target_m' + i]); return v !== null ? v : (tb !== null && bob[j] !== null ? Math.round(tb * bob[j]) : null); });
    tgt[b + '|' + k] = { bulanan: tb, minggu: tm };
  }
  const n0 = v => (v === '' || v === null || v === undefined ? null : num(v));
  const add = (a, v) => (v === null ? a : (a === null ? 0 : a) + v);
  const blank = () => ({ hari: 0, tglAkhir: '', tunai: null, qris: null, ojol: null, nt: null, omzet: null, ch_offline: null, ch_whatsapp: null, ch_ojol: null, ch_organik: null, ch_ads: null, ch_online: null, ch_live: null, hariAdmin: 0, verif: 0 });
  const acc = (g, r) => {
    g.hari++; if (r.tanggal > g.tglAkhir) g.tglAkhir = r.tanggal;
    g.tunai = add(g.tunai, n0(r.tunai)); g.qris = add(g.qris, n0(r.qris)); g.ojol = add(g.ojol, n0(r.ojol));
    g.nt = add(g.nt, n0(r.non_tunai_total)); g.omzet = add(g.omzet, n0(r.omzet));
    for (const c of ['ch_offline','ch_whatsapp','ch_ojol','ch_organik','ch_ads','ch_online','ch_live']) g[c] = add(g[c], n0(r[c]));
    if (t(r.ch_online_sumber) === 'admin') g.hariAdmin++;
    if (t(r.status).toLowerCase() === 'terverifikasi') g.verif++;
  };
  const dim = b => new Date(Date.UTC(+b.slice(0, 4), +b.slice(5, 7), 0)).getUTCDate();
  const W = [[1, 7], [8, 14], [15, 21], [22, 31]];
  const M = {}, B = {}, Y = {};
  for (const r of dataRows) {
    const tg = t(r.tanggal), k = t(r.outlet_kode); if (!tg || !k) continue;
    const b = tg.slice(0, 7), y = tg.slice(0, 4), w = mingguKe(+tg.slice(8));
    if (bulanList.includes(b)) {
      acc(M[b + '|M' + w + '|' + k] = M[b + '|M' + w + '|' + k] || blank(), r); acc(M[b + '|M' + w + '|ALL'] = M[b + '|M' + w + '|ALL'] || blank(), r);
      acc(B[b + '|' + k] = B[b + '|' + k] || blank(), r); acc(B[b + '|ALL'] = B[b + '|ALL'] || blank(), r);
    }
    if (tahunList.includes(+y)) { acc(Y[y + '|' + k] = Y[y + '|' + k] || blank(), r); acc(Y[y + '|ALL'] = Y[y + '|ALL'] || blank(), r); }
  }
  // outlet yang punya target tapi belum ada data tetap muncul (omzet kosong, bukan 0)
  for (const key of Object.keys(tgt)) {
    const [b, k] = key.split('|'); if (!bulanList.includes(b)) continue;
    B[b + '|' + k] = B[b + '|' + k] || blank(); B[b + '|ALL'] = B[b + '|ALL'] || blank();
    for (let w = 1; w <= 4; w++) { M[b + '|M' + w + '|' + k] = M[b + '|M' + w + '|' + k] || blank(); M[b + '|M' + w + '|ALL'] = M[b + '|M' + w + '|ALL'] || blank(); }
  }
  const sumT = (b, f) => { let s = null; for (const [kk, v] of Object.entries(tgt)) if (kk.startsWith(b + '|') && kk !== b + '|ALL') { const x = f(v); if (x !== null) s = (s || 0) + x; } return s; };
  const r2 = v => (v === null ? '' : Math.round(v * 10000) / 10000);
